                linkToParent(greatPa, leftRotate(grandpa));
            }

            if (!isParentLeftSide && isLeftSide) { // 右-左 -> 右旋 -> 右-右-> 左旋
                linkToParent(grandpa, rightRotate(parent));
                linkToParent(greatPa, leftRotate(grandpa));
